#!/usr/bin/env python3
import os
import sys
import re
import glob
import time
import shutil
import tty
import termios
import select
import subprocess
import configparser
from datetime import datetime, date, timedelta
import calendar

VERSION = "commit-e3efeaa30714750f300e0d885d80a6c0fc3ff0b2"

def print_help(config_path_default):
    home = os.path.expanduser("~")
    help_text = f"""Captain's Log (caps-log)! A CLI journalig tool.
Version: {VERSION}
Allowed options:
  -h [ --help ]         show this message
  -c [ --config ] arg   override the default config file path 
                        ({config_path_default})
  --log-dir-path arg    path where log files are stored
  --log-name-format arg format in which log entry markdown files are saved
  --sunday-start        have the calendar display sunday as first day of the 
                        week
  --first-line-section  override the default behaviour of ignoring sections 
                        (lines starting with `#`) in the first line of a log 
                        entry file
  --password arg        password for encrypted log repositories or to be used 
                        with --encrypt/--decrypt
  --encrypt             apply encryption to all logs in log dir path (needs 
                        --password)
  --decrypt             apply decryption to all logs in log dir path (needs 
                        --password)
"""
    sys.stdout.write(help_text)
    sys.exit(0)

def print_error(msg):
    sys.stderr.write(f"Captain's log encountered an error: \n {msg}\n")
    sys.exit(1)

# OpenSSL Crypto Helpers
def encrypt_data(data: bytes, password: str) -> bytes:
    try:
        proc = subprocess.run(
            ['openssl', 'enc', '-aes-128-cfb', '-md', 'md5', '-nosalt', '-pass', f'pass:{password}'],
            input=data,
            capture_output=True,
            check=True
        )
        return proc.stdout
    except Exception as e:
        print_error(f"Encryption failed: {e}")

def decrypt_data(data: bytes, password: str) -> bytes:
    try:
        proc = subprocess.run(
            ['openssl', 'enc', '-d', '-aes-128-cfb', '-md', 'md5', '-nosalt', '-pass', f'pass:{password}'],
            input=data,
            capture_output=True,
            check=True
        )
        return proc.stdout
    except Exception as e:
        print_error(f"Decryption failed: {e}")

def parse_markdown(content: str, first_line_section: bool = False):
    sections = []
    current_section = "<root>"
    current_tags = []

    lines = content.splitlines()
    first_header_seen = False

    for line in lines:
        sline = line.strip()
        if sline.startswith('#'):
            header_text = sline.lstrip('#').strip()
            if not first_header_seen and not first_line_section:
                first_header_seen = True
                continue
            first_header_seen = True

            if header_text:
                if current_tags or current_section != "<root>":
                    sections.append((current_section, current_tags))
                current_section = header_text.lower()
                current_tags = []
        elif sline.startswith('*'):
            tag_text = sline.lstrip('*').strip()
            tag_title = re.split(r'[\(:]', tag_text)[0].strip().lower()
            if tag_title:
                current_tags.append(tag_title)

    if current_tags or current_section != "<root>":
        sections.append((current_section, current_tags))

    return sections

def main():
    raw_args = sys.argv[1:]

    # Check -h or --help first
    default_config_path = os.path.expanduser("~/.caps-log/config.ini")
    if "-h" in raw_args or "--help" in raw_args:
        print_help(default_config_path)

    # Parse CLI Arguments
    config_path = default_config_path
    cli_log_dir_path = None
    cli_log_name_format = None
    cli_sunday_start = False
    cli_first_line_section = False
    cli_password = None
    cli_encrypt = False
    cli_decrypt = False

    idx = 0
    while idx < len(raw_args):
        arg = raw_args[idx]
        if arg in ["-c", "--config"]:
            if idx + 1 >= len(raw_args):
                print_error(f"option '{arg}' requires an argument")
            config_path = raw_args[idx + 1]
            idx += 2
        elif arg == "--log-dir-path":
            if idx + 1 >= len(raw_args):
                print_error(f"option '{arg}' requires an argument")
            cli_log_dir_path = raw_args[idx + 1]
            idx += 2
        elif arg == "--log-name-format":
            if idx + 1 >= len(raw_args):
                print_error(f"option '{arg}' requires an argument")
            cli_log_name_format = raw_args[idx + 1]
            idx += 2
        elif arg == "--sunday-start":
            cli_sunday_start = True
            idx += 1
        elif arg == "--first-line-section":
            cli_first_line_section = True
            idx += 1
        elif arg == "--password":
            if idx + 1 >= len(raw_args):
                print_error(f"option '{arg}' requires an argument")
            cli_password = raw_args[idx + 1]
            idx += 2
        elif arg == "--encrypt":
            cli_encrypt = True
            idx += 1
        elif arg == "--decrypt":
            cli_decrypt = True
            idx += 1
        else:
            print_error(f"unrecognised option '{arg}'")

    config_path = os.path.expanduser(config_path)

    if not os.path.exists(config_path):
        print_error(f"Failed to open file: {config_path}")

    cp = configparser.ConfigParser(strict=False)
    try:
        with open(config_path, "r", encoding="utf-8") as f:
            cp.read_string("[GLOBAL]\n" + f.read())
    except Exception:
        pass

    log_dir_path = cli_log_dir_path or cp.get("GLOBAL", "log-dir-path", fallback="~/.caps-log/day/")
    log_dir_path = os.path.expanduser(log_dir_path)

    log_name_format = cli_log_name_format or cp.get("GLOBAL", "log-filename-format", fallback="d%y_%m_%d.md")
    sunday_start = cli_sunday_start or cp.getboolean("GLOBAL", "sunday-start", fallback=False)
    first_line_section = cli_first_line_section or cp.getboolean("GLOBAL", "first-line-section", fallback=False)
    password = cli_password or cp.get("GLOBAL", "password", fallback=None)

    # Git options
    git_enabled = cp.getboolean("git", "enable-git-log-repo", fallback=False)
    git_ssh_key = cp.get("git", "ssh-key-path", fallback=None)
    git_ssh_pub = cp.get("git", "ssh-pub-key-path", fallback=None)
    git_repo_root = cp.get("git", "repo-root", fallback=None)
    git_remote = cp.get("git", "remote-name", fallback="origin")
    git_branch = cp.get("git", "main-branch-name", fallback="main")

    if git_enabled:
        if git_ssh_key and not os.path.exists(os.path.expanduser(git_ssh_key)):
            print_error(f"SSH key does not exist: {git_ssh_key}")
        if git_repo_root:
            git_repo_root = os.path.expanduser(git_repo_root)
            if not os.path.abspath(log_dir_path).startswith(os.path.abspath(git_repo_root)):
                print_error(f"log-dir-path is not inside repo-root")

    # Calendar Events options
    events_window = cp.getint("calendar-events", "recent-events-window", fallback=60)
    events_list = []
    for section_name in cp.sections():
        if section_name.startswith("calendar-events."):
            parts = section_name.split(".")
            cat_name = parts[1] if len(parts) > 1 else "events"
            ev_name = cp.get(section_name, "name", fallback="")
            ev_date = cp.get(section_name, "date", fallback="")
            if ev_name and ev_date:
                events_list.append({'category': cat_name, 'name': ev_name, 'date_str': ev_date})

    # Validate encrypt / decrypt flags
    if cli_encrypt:
        if not password:
            print_error("Password must be provided when encrypting logs!")
        os.makedirs(log_dir_path, exist_ok=True)
        sys.stdout.write("Applying crypto...\n")
        cle_file = os.path.join(log_dir_path, ".cle")
        cle_enc = encrypt_data(b"encryption-marker:", password)
        with open(cle_file, "wb") as f:
            f.write(cle_enc)

        for root, dirs, files in os.walk(log_dir_path):
            for file in files:
                if file.endswith(".md"):
                    fp = os.path.join(root, file)
                    raw_data = open(fp, "rb").read()
                    try:
                        enc_data = encrypt_data(raw_data, password)
                        with open(fp, "wb") as f:
                            f.write(enc_data)
                    except Exception:
                        pass
        sys.exit(0)

    if cli_decrypt:
        if not password:
            print_error("Password must be provided when decrypting logs!")
        os.makedirs(log_dir_path, exist_ok=True)
        sys.stdout.write("Applying crypto...\n")
        cle_file = os.path.join(log_dir_path, ".cle")
        if os.path.exists(cle_file):
            os.remove(cle_file)

        for root, dirs, files in os.walk(log_dir_path):
            for file in files:
                if file.endswith(".md"):
                    fp = os.path.join(root, file)
                    raw_data = open(fp, "rb").read()
                    try:
                        dec_data = decrypt_data(raw_data, password)
                        with open(fp, "wb") as f:
                            f.write(dec_data)
                    except Exception:
                        pass
        sys.exit(0)

    # Ensure log directory exists
    os.makedirs(log_dir_path, exist_ok=True)

    # Check .cle file
    cle_file = os.path.join(log_dir_path, ".cle")
    is_encrypted = os.path.exists(cle_file)

    if is_encrypted:
        if password is None:
            password = run_password_modal(log_dir_path)
            if not password:
                print_error("Password is required to open encrypted log repository!")

        try:
            cle_raw = open(cle_file, "rb").read()
            cle_dec = decrypt_data(cle_raw, password)
            if b"encryption-marker:" not in cle_dec:
                print_error("Invalid password provided!")
        except Exception:
            print_error("Invalid password provided!")
    else:
        if password is not None:
            print_error("Password provided for a non encrypted repository!")

    # Start TUI Application
    run_tui(
        log_dir_path=log_dir_path,
        log_name_format=log_name_format,
        sunday_start=sunday_start,
        first_line_section=first_line_section,
        password=password,
        is_encrypted=is_encrypted,
        git_enabled=git_enabled,
        git_repo_root=git_repo_root,
        git_remote=git_remote,
        git_branch=git_branch,
        events_window=events_window,
        events_list=events_list
    )

